<script setup>
import {computed} from 'vue'
import ContentLink from './ContentLink.vue'
import SiteIcon from './SiteIcon.vue'
import PublicBusinessHours from './PublicBusinessHours.vue'
import BranchSelector from './BranchSelector.vue'
import {useRestaurantInfo} from '../../composables/useRestaurantInfo'
import {safeContentUrl} from '../../utils/contentUrl'
const props=defineProps({section:Object,banner:Object,pageTitle:String}),restaurant=useRestaurantInfo(),data=computed(()=>props.section.data||{}),image=computed(()=>safeContentUrl(props.banner?.image_url||data.value.image_url))
const heroStyle=computed(()=>({'--cms-image':'url('+JSON.stringify(image.value)+')','--cms-mobile-image':'url('+JSON.stringify(safeContentUrl(props.banner?.mobile_image_url)||image.value)+')',backgroundSize:'cover',backgroundPosition:'center'}))
const buttonText=(kind)=>props.banner?.[kind==='primary'?'button_text':'secondary_button_text']||data.value[kind+'_button_text']
const buttonUrl=(kind)=>safeContentUrl(props.banner?.[kind==='primary'?'button_url':'secondary_button_url']||data.value[kind+'_button_url'])
</script>
<template><section v-if="section.type==='hero'" class="hero" :id="section.key==='hero'?'home':undefined"><div v-if="image" class="hero-art" role="img" :aria-label="section.title||banner?.title||''" :style="heroStyle"/><div class="hero-shade"/><div class="container hero-inner"><div class="hero-copy"><span v-if="section.subtitle" class="eyebrow">{{ section.subtitle }}</span><h1>{{ banner?.title||section.title||pageTitle }}</h1><p>{{ banner?.subtitle||section.content }}</p><div class="hero-buttons"><ContentLink v-for="kind in ['primary','secondary']" v-show="buttonUrl(kind)&&buttonText(kind)" :key="kind" class="button" :class="kind==='primary'?'button-primary':'button-outline'" :url="buttonUrl(kind)">{{ buttonText(kind) }} <SiteIcon name="arrow-left"/></ContentLink></div></div></div></section>
<section v-else-if="section.type==='features'" class="features"><div class="container features-grid"><article v-for="(item,index) in data.items||[]" :key="index"><SiteIcon :name="['drumstick','flame','badge-check','truck'][index%4]"/><div><h3>{{ item.title }}</h3><p>{{ item.description }}</p></div></article></div></section>
<section v-else-if="section.type==='image_text'" class="about container"><div v-if="image" class="about-photo" role="img" :aria-label="section.title||''" :style="{backgroundImage:'url('+JSON.stringify(image)+')',backgroundSize:'cover',backgroundPosition:'center'}"/><div class="about-copy"><span class="section-kicker">{{ section.subtitle }}</span><h2>{{ section.title }}</h2><p class="cms-text">{{ section.content }}</p><ContentLink v-for="kind in ['primary','secondary']" v-show="buttonUrl(kind)&&buttonText(kind)" :key="kind" class="button button-primary button-small" :url="buttonUrl(kind)">{{ buttonText(kind) }}</ContentLink></div></section>
<section v-else-if="section.type==='cta'" class="cta container"><div class="cta-symbol"><SiteIcon name="utensils"/></div><div><h2>{{ section.title }}</h2><p>{{ section.content||section.subtitle }}</p></div><ContentLink v-if="buttonUrl('primary')&&buttonText('primary')" class="button button-primary" :url="buttonUrl('primary')">{{ buttonText('primary') }}</ContentLink><ContentLink v-if="buttonUrl('secondary')&&buttonText('secondary')" class="text-button" :url="buttonUrl('secondary')">{{ buttonText('secondary') }}</ContentLink></section>
<section v-else-if="section.type==='contact'" class="container section-space"><div class="section-heading"><div><h2>{{ section.title }}</h2><p>{{ section.subtitle }}</p></div></div><p class="cms-text">{{ section.content }}</p><PublicBusinessHours v-if="section.key==='working_hours'"/><template v-else><BranchSelector/><p>{{ restaurant.address }}</p><a v-if="restaurant.mapHref" class="footer-link" :href="restaurant.mapHref" target="_blank" rel="noopener noreferrer">الوصول إلى الفرع</a><p><a v-if="restaurant.phoneHref" :href="restaurant.phoneHref"><bdi>{{ restaurant.phone }}</bdi></a></p><a v-if="restaurant.whatsappHref" class="footer-link" :href="restaurant.whatsappHref" target="_blank" rel="noopener noreferrer">واتساب</a><p><a v-if="restaurant.email" :href="'mailto:'+restaurant.email"><bdi>{{ restaurant.email }}</bdi></a></p></template>
</section>
<section v-else class="container section-space"><div class="section-heading"><div><span class="section-kicker">{{ section.subtitle }}</span><h2>{{ section.title }}</h2></div></div><p class="cms-text">{{ section.content }}</p></section></template>
<style scoped>.hero-art{background-image:var(--cms-image)}@media(max-width:600px){.hero-art{background-image:var(--cms-mobile-image)}}</style>

